// Pure helpers shared by A (mission) and B (explore). No DOM, no numbers from the design:
// every result is computed from arrays/objects passed in (web/data series, LOLA grid, API payloads).
// Source of truth: this .ts file. mission-calc.js is generated by `npm --prefix web run build:ts`.
import { sealFor } from "../core/data.js";
import type { ApiResult, Seal } from "../core/data.js";

export interface View { span: number; cx: number; cy: number; }
export interface CellGrid { x0: number; y0: number; dx: number; nx: number; ny: number; }
export interface Runs { losses: number; longest: number; firstLoss: number | null; firstReturn: number | null; }
export interface Transition { hours_from_start: number; kind: string; epoch_utc: string; resolution_seconds: number; }
/** GET /api/sites/{id}/sky, as far as skyNext reads it. */
export interface SkyPayload { science_status?: string; next_transitions?: Record<string, unknown>; }
export interface SkyNext { from: "api"; seal: Seal; hours: number | null; kind: string | null; reason?: string | null; at?: string; resolution?: number; }
export interface HorizonPoint { az: number; el: number; }
export type RampName = "altitude" | "slope" | "sun" | "earth";
type Rgb = number[];

/**
 * Visibility runs inside the window [i0, i0+n) of a margin array (visible = margin >= 0).
 * → { losses, longest, firstLoss, firstReturn } ; offsets in steps from i0, null when absent.
 * Returns null when the window is outside the array (caller shows "—" + N/D).
 */
export function runs(margin: ArrayLike<number> | null | undefined, i0: number, n: number): Runs | null {
  if (!margin || i0 < 0 || n <= 0 || i0 + n > margin.length) return null;
  let losses = 0, longest = 0, cur = 0, firstLoss: number | null = null, firstReturn: number | null = null;
  for (let k = 0; k < n; k++) {
    const v = margin[i0 + k] >= 0;
    const prev = k > 0 ? margin[i0 + k - 1] >= 0 : null;
    if (!v) { if (cur === 0) losses++; cur++; if (cur > longest) longest = cur; } else cur = 0;
    if (k > 0 && prev && !v && firstLoss == null) firstLoss = k;
    if (k > 0 && prev === false && v && firstReturn == null) firstReturn = k;
  }
  return { losses, longest, firstLoss, firstReturn };
}

/** Day label index (1-based) of an hour offset, null-safe. */
export const dayOf = (h: number | null | undefined): number | null => (h == null ? null : Math.floor(h / 24) + 1);

/** Value + unit text; missing → nd ("—"). */
export function fmtVal(v: number | null | undefined, fmtNum: (v: number, digits: number) => string, nd: string, digits = 0, unit = ""): string {
  if (v == null || (typeof v === "number" && !Number.isFinite(v))) return nd;
  return fmtNum(v, digits) + unit;
}

/** "lat° S · lon° E" with exactly 3 decimals (lon east 0..360). */
export function coordParts(lat: number, lon: number): { lat: number; hemi: "S" | "N"; lonE: number } | null {
  if (!Number.isFinite(lat) || !Number.isFinite(lon)) return null;
  return { lat: Math.abs(lat), hemi: lat < 0 ? "S" : "N", lonE: ((lon % 360) + 360) % 360 };
}
export function coordText(lat: number, lon: number, fmtNum: (v: number, digits: number) => string, nd: string): string {
  const c = coordParts(lat, lon); if (!c) return nd;
  return `${fmtNum(c.lat, 3)}° ${c.hemi} · ${fmtNum(c.lonE, 3)}° E`;
}
/** Parse a typed coordinate: "-89.5, 220" or "89,5 S 220 E". null when not a south-polar point. */
export function parseCoord(text: unknown): { lat: number; lon: number } | null {
  const s = String(text || "").trim().toUpperCase();
  const m = s.match(/^(-?\d+(?:[.,]\d+)?)\s*°?\s*([NS])?\s*[,;·\s]\s*(-?\d+(?:[.,]\d+)?)\s*°?\s*([EW])?$/);
  if (!m) return null;
  let lat = Number(m[1].replace(",", ".")), lon = Number(m[3].replace(",", "."));
  if (m[2] === "S") lat = -Math.abs(lat); if (m[2] === "N") lat = Math.abs(lat);
  if (m[4] === "W") lon = -lon;
  if (!(lat >= -90 && lat < 0) || !Number.isFinite(lon)) return null;
  return { lat, lon };
}

/** Screen pixel → polar stereographic metres, same transform as core/terrain.js. */
export function pxToStereo(px: number, py: number, view: View, W: number, H: number): [number, number] {
  const mpp = view.span / Math.min(W, H);
  return [view.cx + (px - W / 2) * mpp, view.cy - (py - H / 2) * mpp];
}
export function stereoToPx(x: number, y: number, view: View, W: number, H: number): [number, number] {
  const mpp = view.span / Math.min(W, H);
  return [W / 2 + (x - view.cx) / mpp, H / 2 - (y - view.cy) / mpp];
}

/** Index of the LOLA/PGDA cell (row 0 = min y) or -1 outside. */
export function cellIndex(grid: CellGrid, x: number, y: number): number {
  const i = Math.round((x - grid.x0) / grid.dx), j = Math.round((y - grid.y0) / grid.dx);
  return i >= 0 && j >= 0 && i < grid.nx && j < grid.ny ? j * grid.nx + i : -1;
}
/** PGDA uint8 percent at a point; > 100 or outside → null. */
export function pgdaAt(grid: CellGrid, arr: ArrayLike<number> | null | undefined, x: number, y: number): number | null {
  const k = cellIndex(grid, x, y); if (k < 0 || !arr) return null;
  const v = arr[k]; return v > 100 ? null : v;
}

/**
 * Direction of azimuth az (deg clockwise from local north) drawn on the south-polar map,
 * in screen pixels (y down). Local north points away from the pole.
 */
export function mapDir(lonDeg: number, azDeg: number): [number, number] {
  const l = lonDeg * Math.PI / 180, a = azDeg * Math.PI / 180;
  const north = [Math.sin(l), Math.cos(l)], east = [Math.cos(l), -Math.sin(l)];
  const x = north[0] * Math.cos(a) + east[0] * Math.sin(a), y = north[1] * Math.cos(a) + east[1] * Math.sin(a);
  return [x, -y];
}

/**
 * "Now at site" from GET /api/sites/{id}/sky. The seal follows the payload's science_status
 * (synthetic → SIM; the top seal only for the exact top state). null transition → N/D with the reason.
 */
export function skyNext(resp: ApiResult<SkyPayload | null> | null | undefined, body: string): SkyNext {
  if (!resp || !resp.ok) return { from: "api", seal: "N/D", hours: null, kind: null, reason: resp?.error || null };
  const nt = resp.data?.next_transitions, tr = nt?.[body] as Transition | null | undefined;
  const seal = sealFor(resp.data?.science_status);
  if (!tr) return { from: "api", seal: "N/D", hours: null, kind: null, reason: (nt?.[body + "_null_reason"] as string | undefined) || null };
  return { from: "api", seal, hours: tr.hours_from_start, kind: tr.kind, at: tr.epoch_utc, resolution: tr.resolution_seconds };
}

/** Horizon profile → SVG polyline points over az 0..360 (x) and elevation (y, up). */
export function horizonPoints(horizon: HorizonPoint[] | null | undefined, w: number, h: number, elMin: number, elMax: number): string {
  if (!Array.isArray(horizon) || !horizon.length || !(elMax > elMin)) return "";
  const y = (el: number): number => h - ((el - elMin) / (elMax - elMin)) * h;
  return horizon.map(p => `${((p.az / 360) * w).toFixed(1)},${y(p.el).toFixed(1)}`).join(" ");
}
export function elRange(horizon: HorizonPoint[] | null | undefined, extra: number[] = []): [number, number] | null {
  const v = [...(horizon || []).map(p => p.el), ...extra.filter(Number.isFinite)];
  if (!v.length) return null;
  const lo = Math.min(...v), hi = Math.max(...v), pad = (hi - lo) * 0.15 || 1;
  return [lo - pad, hi + pad];
}

/** Battery margin: declared autonomy (user input, SIM) minus longest night (data). */
export function batteryMargin(autonomyH: number, longestNightH: number): number | null {
  if (!Number.isFinite(autonomyH) || autonomyH <= 0 || !Number.isFinite(longestNightH)) return null;
  return autonomyH - longestNightH;
}

/** Colour ramps for the terrain layers (t in 0..1). */
const lerp = (a: Rgb, b: Rgb, t: number): Rgb => a.map((v, i) => Math.round(v + (b[i] - v) * t));
function ramp(stops: Rgb[], t: number): Rgb { t = Math.max(0, Math.min(1, t)); const s = t * (stops.length - 1), i = Math.min(stops.length - 2, Math.floor(s)); return lerp(stops[i], stops[i + 1], s - i); }
export const RAMPS: Record<RampName, Rgb[]> = {
  altitude: [[16, 30, 74], [58, 82, 120], [120, 124, 112], [196, 176, 92], [255, 209, 102]],
  slope: [[40, 20, 70], [120, 60, 160], [200, 90, 170], [250, 150, 190]],
  sun: [[10, 10, 14], [110, 70, 20], [200, 150, 50], [255, 209, 102]],
  earth: [[8, 12, 24], [30, 70, 140], [76, 155, 255], [190, 220, 255]],
};
export const rampColor = (name: RampName, t: number): Rgb => ramp(RAMPS[name], t);
export const rampCss = (name: RampName): string => `linear-gradient(90deg, ${RAMPS[name].map(c => `rgb(${c})`).join(", ")})`;

/** 8-point compass index (0 = N, 1 = NE … 7 = NW) of an azimuth in degrees clockwise from north; null when missing. */
export function compassIndex(azDeg: number): number | null {
  if (!Number.isFinite(azDeg)) return null;
  return Math.round((((azDeg % 360) + 360) % 360) / 45) % 8;
}
